import{_ as l,o as i,c as e,a2 as o}from"./chunks/framework.DnrXFDHb.js";const c=JSON.parse('{"title":"常用工具","description":"","frontmatter":{},"headers":[],"relativePath":"tools/common-tools.md","filePath":"tools/common-tools.md","lastUpdated":1786350421000}'),t={name:"tools/common-tools.md"};function r(n,a,h,s,p,d){return i(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="常用工具" tabindex="-1">常用工具 <a class="header-anchor" href="#常用工具" aria-label="Permalink to &quot;常用工具&quot;">​</a></h1><p>一句话：工具把模型、数据和流程包装成可用体验。选择工具时要同时看任务、隐私、成本、硬件、可控程度和维护负担。</p><h2 id="web-ai-助手" tabindex="-1">Web AI 助手 <a class="header-anchor" href="#web-ai-助手" aria-label="Permalink to &quot;Web AI 助手&quot;">​</a></h2><p>ChatGPT、Claude、Gemini 等 Web AI 助手适合快速问答、写作、总结、翻译、代码辅助和文件分析。</p><p>适合：</p><ul><li>快速验证想法，不搭建技术环境。</li><li>处理一次性文本、表格、图片或代码任务。</li><li>使用平台提供的搜索、文件和多模态能力。</li></ul><p>注意不要上传无权处理的隐私、商业机密或受限制数据，并核对平台当前的数据使用、费用和内容规则。</p><h2 id="api-与-sdk" tabindex="-1">API 与 SDK <a class="header-anchor" href="#api-与-sdk" aria-label="Permalink to &quot;API 与 SDK&quot;">​</a></h2><p>API 适合把模型能力接入自己的应用或固定流程，例如分类、信息抽取、结构化输出、问答和工具调用。</p><p>实际项目还需要处理：</p><ul><li>密钥和权限管理。</li><li>请求超时、限流、重试和错误记录。</li><li>输入输出校验，特别是 JSON 与 Function Calling 参数。</li><li>成本、延迟、模型版本和回归评估。</li><li>敏感数据脱敏与审计。</li></ul><p>API 调用成功只代表请求完成，不代表结果已经正确。</p><h2 id="本地模型工具" tabindex="-1">本地模型工具 <a class="header-anchor" href="#本地模型工具" aria-label="Permalink to &quot;本地模型工具&quot;">​</a></h2><p>Ollama、LM Studio、llama.cpp 等工具可以在本地下载和运行兼容模型。</p><p>适合：</p><ul><li>需要离线使用或更强的数据控制。</li><li>想比较不同开源模型和量化版本。</li><li>有合适的 CPU、内存或显卡资源。</li></ul><p>本地运行仍要管理模型来源、许可证、磁盘空间、显存占用、上下文长度和推理速度。开源或本地不自动等于无限制使用。</p><h2 id="rag-与-agent-工具" tabindex="-1">RAG 与 Agent 工具 <a class="header-anchor" href="#rag-与-agent-工具" aria-label="Permalink to &quot;RAG 与 Agent 工具&quot;">​</a></h2><p>LangChain、LlamaIndex、Dify 等工具可以组织文档检索、模型调用、结构化步骤和外部工具。</p><p>它们能减少重复开发，但不会自动解决：</p><ul><li>文档切分和检索质量。</li><li>来源引用和版本管理。</li><li>工具权限、输入校验和失败恢复。</li><li>Agent 循环、成本失控和不可重复行为。</li><li>评估样例与人工复核。</li></ul><p>先用简单流程验证数据和任务，再决定是否需要完整 Agent 框架。</p><h2 id="ai-绘画工具" tabindex="-1">AI 绘画工具 <a class="header-anchor" href="#ai-绘画工具" aria-label="Permalink to &quot;AI 绘画工具&quot;">​</a></h2><h3 id="web-图像平台" tabindex="-1">Web 图像平台 <a class="header-anchor" href="#web-图像平台" aria-label="Permalink to &quot;Web 图像平台&quot;">​</a></h3><p>适合快速体验和简单创作，不需要本地显卡。使用前检查额度、内容规则、上传素材隐私和商业许可。</p><h3 id="stable-diffusion-webui" tabindex="-1">Stable Diffusion WebUI <a class="header-anchor" href="#stable-diffusion-webui" aria-label="Permalink to &quot;Stable Diffusion WebUI&quot;">​</a></h3><p>按钮式本地 AI 绘画界面，适合传统 SD1.5 / SDXL 工作流、插件生态和常见图生图操作。</p><h3 id="comfyui" tabindex="-1">ComfyUI <a class="header-anchor" href="#comfyui" aria-label="Permalink to &quot;ComfyUI&quot;">​</a></h3><p>节点式工作流工具，适合学习模型数据流、精细控制、复用流程，以及搭建图生图、局部重绘、放大和参考图控制。</p><h2 id="模型与资料管理" tabindex="-1">模型与资料管理 <a class="header-anchor" href="#模型与资料管理" aria-label="Permalink to &quot;模型与资料管理&quot;">​</a></h2><p>无论使用 LLM 还是图像模型，都建议记录：</p><ul><li>模型名称、版本、来源和文件校验信息。</li><li>模型卡、许可证、推荐输入和用途限制。</li><li>Prompt、参数、评估样例和已知失败模式。</li><li>RAG 文档来源、更新时间、切分方式和索引版本。</li><li>工作流依赖、插件或节点版本。</li></ul><h2 id="图像后期与生产工具" tabindex="-1">图像后期与生产工具 <a class="header-anchor" href="#图像后期与生产工具" aria-label="Permalink to &quot;图像后期与生产工具&quot;">​</a></h2><p>AI 出图通常仍需要裁剪、调色、瑕疵修复、文字排版、放大和锐化。常见工具包括 Photoshop、Affinity Photo、Krita、Photopea 和 GIMP。</p><p>用于公开发布时，还应保留来源记录并做人工筛选。</p><h2 id="如何选择" tabindex="-1">如何选择 <a class="header-anchor" href="#如何选择" aria-label="Permalink to &quot;如何选择&quot;">​</a></h2><ul><li>一次性体验：先用 Web AI 助手或图像平台。</li><li>固定应用流程：使用 API，并建立日志、校验和评估。</li><li>隐私或离线要求：评估本地模型和硬件成本。</li><li>经常查询自有资料：先做简单 RAG，再考虑 Agent。</li><li>需要精细图像控制：选择 WebUI 或 ComfyUI，并保留可复现工作流。</li></ul><p>继续阅读 <a href="/resources/websites">常用网站</a> 和 <a href="/resources/tutorials">精选教程</a>。</p>',38)])])}const b=l(t,[["render",r]]);export{c as __pageData,b as default};
